import { spawnSync } from "node:child_process";
import fs2 from "node:fs";
import path3 from "node:path";

// src/shared/node-version.ts
var MINIMUM_NODE_VERSION = "22.13.0";
var parseVersion = (value) => {
	const match = /^v?(\d+)\.(\d+)\.(\d+)/.exec(value.trim());
	if (!match) return;
	return [Number(match[1]), Number(match[2]), Number(match[3])];
};
var assertSupportedNodeVersion = (version, minimum = MINIMUM_NODE_VERSION) => {
	const parsed = parseVersion(version);
	const parsedMinimum = parseVersion(minimum);
	if (!parsed || !parsedMinimum) {
		throw new Error(`Cannot parse Node.js version ${JSON.stringify(version)}`);
	}
	let comparison = 0;
	for (let index = 0; index < parsed.length; index += 1) {
		comparison = parsed[index] - parsedMinimum[index];
		if (comparison !== 0) break;
	}
	if (comparison < 0) {
		throw new Error(
			`Premind requires Node.js ${minimum} or newer for stable node:sqlite support; found ${version.trim()}`,
		);
	}
};

// src/client/node-runtime.ts
var findOnPath = (name, environmentPath = process.env.PATH ?? "") => {
	const names =
		process.platform === "win32"
			? [`${name}.exe`, `${name}.cmd`, name]
			: [name];
	for (const directory of environmentPath.split(path3.delimiter)) {
		if (!directory) continue;
		for (const candidateName of names) {
			const candidate = path3.join(directory, candidateName);
			if (fs2.existsSync(candidate)) return candidate;
		}
	}
	return;
};
var resolveNodeRuntime = (options = {}) => {
	const executable =
		options.executable ?? findOnPath("node", options.environmentPath);
	if (!executable) {
		throw new Error(
			`Cannot start Premind: Node.js ${MINIMUM_NODE_VERSION} or newer is not available on PATH`,
		);
	}
	const result = spawnSync(executable, ["--version"], {
		encoding: "utf8",
		timeout: 5000,
	});
	if (result.error) {
		throw new Error(
			`Cannot run Node.js at ${executable}: ${result.error.message}`,
			{
				cause: result.error,
			},
		);
	}
	if (result.status !== 0) {
		throw new Error(
			`Cannot determine Node.js version at ${executable}: exit ${result.status ?? "unknown"}`,
		);
	}
	const version = result.stdout.trim();
	assertSupportedNodeVersion(version);
	return { executable, version };
};

