		return await Promise.race([
			operation,
			new Promise((_resolve, reject) => {
				timer = setTimeout(
					() => reject(new Error(`Codex cleanup exceeded ${timeoutMs}ms`)),
					timeoutMs,
				);
			}),
		]);
